internal object DuaElDraft3 {
    val MAP: Map<String, DuaText> = mapOf(
        "dua_seeing_first_fruit" to DuaText("Βλέποντας τον Πρώτο Φρούτο", "Ω Αλλάχ, ευλόγησέ μας στους καρπούς μας, ευλόγησέ μας στην πόλη μας και ευλόγησέ μας στο σα' και στα μέτρα μας.", "Βλέποντας το πρώτο φρούτο της εποχής.", "Μια ντουά για ευλογία στην προμήθεια και στην πόλη κάποιου."),
        "dua_good_news" to DuaText("Μετά από ευχάριστα νέα", "Όλος ο έπαινος είναι για τον Αλλάχ, με την εύνοια του οποίου ολοκληρώνονται τα καλά πράγματα.", "Κατά τη λήψη καλών ειδήσεων (και να κάνετε την υπόκλιση της ευγνωμοσύνης).", "Ο Προφήτης ﷺ το είπε όταν είδε κάτι που του άρεσε."),
        "dua_looking_mirror" to DuaText("Κοιτάζοντας στον Καθρέφτη", "Ω Αλλάχ, όπως έκανες την εμφάνισή μου καλή, κάνε και τον χαρακτήρα μου καλό.", "Όταν κοιτάζεσαι στον καθρέφτη.", "Ο Προφήτης ﷺ έκανε αυτή τη ντουά (είναι καθιερωμένη ακόμη και χωρίς την αναφορά σε καθρέφτη)."),
        "dua_rabbana_taqabbal" to DuaText("Αποδοχή Πράξεων", "Κύριε μας, δέξου αυτό από εμάς. όντως Εσύ είσαι ο Παντός, ο Παντογνώστης. Και δεχτείτε τη μετάνοιά μας. πράγματι Εσύ είσαι ο Αποδέκτης της μετάνοιας, ο Ελεήμων.", "Ρωτήθηκε από τον Ibrahim και τον Isma'il (AS) κατά την κατασκευή της Κάαμπα.", "Μια δόξα για αποδοχή μετά από κάθε καλή πράξη."),
        "dua_muawwidhat" to DuaText("Οι τρεις σούρες Κουλ (Mu'awwidhat)", "(Σούρα αλ-Ιχλάς) Πείτε: Είναι ο Αλλάχ, ο Ένας. Αλλάχ, ο αυτάρκης. Ούτε γεννά ούτε γεννιέται. Και δεν υπάρχει κανένας συγκρίσιμος με Αυτόν.\n\n(Σούρα αλ-Φαλάκ) Πες: Αναζητώ καταφύγιο στον Κύριο της αυγής, από το κακό αυτού που δημιούργησε, από το κακό του σκότους όταν κατακαθίσει, από το κακό εκείνων που φυσούν κόμπους και από το κακό εκείνου που φθονεί όταν ζηλεύει.\n\n(Σούρα αν-Νας) Πείτε: Αναζητώ καταφύγιο στον Κύριο της ανθρωπότητας, τον Βασιλιά της ανθρωπότητας, τον Θεό της ανθρωπότητας, από το κακό του ψιθυριστή που υποχωρεί, ο οποίος ψιθυρίζει στις καρδιές της ανθρωπότητας, μεταξύ των Τζιν και των ανθρώπων.", "Οι τρεις σούρες τρεις φορές κάθε πρωί και βράδυ, και πριν από τον ύπνο, φυσάνε στα χέρια και σκουπίζουν τα πάνω στο σώμα.", "Η απαγγελία τους τρεις φορές το πρωί και το βράδυ αρκεί ενάντια σε όλα."),
        "dua_sabr" to DuaText("Για υπομονή και σταθερότητα", "Κύριε μας, δώσε μας υπομονή, κάνε τα πόδια μας σταθερά και βοήθησέ μας ενάντια στους απίστους.", "Σε περιόδους κακουχιών και αντιπαραθέσεων.", "Η ντουέτα του στρατού του Ταλούτ."),
        "dua_rabbana_innana_amanna" to DuaText("Συγχώρεση και Προστασία από τη Φωτιά", "Κύριε μας, πιστέψαμε, συγχώρεσε μας τις αμαρτίες μας και προστάτεψε μας από την τιμωρία της Φωτιάς.", "Μια κορανική ντουέτα.", "Μια ντουέτα που αναφέρεται στις ιδιότητες του θεοσεβούμενου."),
        "dua_rabbana_hab_lana_rahmah" to DuaText("Καθοδήγηση στην Υπόθεση μας (Ashab al-Kahf)", "Κύριε μας, χάρισε μας έλεος από τον εαυτό σου και ετοίμασέ μας σωστή καθοδήγηση στην υπόθεση μας.", "Η ντουέτα των ανθρώπων του σπηλαίου.", "Καθοδήγηση σε αποφάσεις και δύσκολες καταστάσεις."),
        "dua_musa_faqir" to DuaText("Dua of Musa (AS) για Προμήθεια", "Κύριε μου, έχω πραγματικά ανάγκη από ό,τι καλό μου στείλεις.", "Αναζητώντας πρόνοια και καλό — η δούα του Μούσα (AS) στο Madyan.", "Μετά από αυτή τη ντουά, ο Αλλάχ παραχώρησε στον Μούσα (AS) σπίτι, δουλειά και σύζυγο."),
        "dua_ayyub" to DuaText("Dua του Ayyub (AS) στην ασθένεια", "(Κύριέ μου,) με έχει αγγίξει το κακό, και Εσύ είσαι ο Ελεήμων από τους ελεήμονες.", "Σε αρρώστια και βάσανα.", "Ο Αλλάχ αφαίρεσε τα βάσανα του Αγιούμπ (AS)."),
        "dua_husn_khatimah" to DuaText("Πέθανε ως Μουσουλμάνος (Yusuf AS)", "Δημιουργέ των ουρανών και της γης, Είσαι ο Προστάτης μου σε αυτόν τον κόσμο και στο εξής. Κάνε με να πεθάνω ως μουσουλμάνος και ένωσε με με τους δίκαιους.", "Μια ντουέτα για ένα καλό τέλος.", "Η ντουά του Προφήτη Γιουσούφ (AS)."),
        "dua_shaitan_hamazat" to DuaText("Καταφύγιο από τους Ψίθυρους των Διαβόλων", "Κύριε μου, καταφεύγω σε Σένα από τους ψιθύρους των διαβόλων, και σε Σένα καταφεύγω, Κύριέ μου, μήπως με πλησιάσουν.", "Καταφύγιο από τους σατανικούς ψίθυρους.", "Μια κορανική ντουέτα αναζήτησης καταφυγίου."),
        "dua_bad_character" to DuaText("Καταφύγιο από τον κακό χαρακτήρα", "Ω Αλλάχ, αναζητώ καταφύγιο σε Σένα από τον κακό χαρακτήρα, τις κακές πράξεις και τις κακές επιθυμίες.", "Καταφύγιο από κακό χαρακτήρα, πράξεις και επιθυμίες.", "Μια ντουέτα καταφυγής από τον Προφήτη ﷺ."),
        "dua_zawal_nimah" to DuaText("Καταφύγιο από την απώλεια των ευλογιών", "Ω Αλλάχ, αναζητώ καταφύγιο σε Σένα από την απώλεια των ευλογιών Σου, από την αλλαγή της ευημερίας που έχεις δώσει, από την ξαφνική τιμωρία Σου και από όλη τη δυσαρέσκειά σου.", "Καταφύγιο από την απώλεια ευλογιών και από την ξαφνική συμφορά.", "Μια ντουέτα του Προφήτη ﷺ."),
        "dua_useless_knowledge" to DuaText("Καταφύγιο από τη μη ωφέλιμη γνώση", "Ω Αλλάχ, ζητώ καταφύγιο σε Σένα από τη γνώση που δεν ωφελεί, από μια καρδιά που δεν φοβάται, από μια ψυχή που δεν είναι ποτέ ικανοποιημένη και από μια ντουέτα που δεν απαντάται.", "Καταφύγιο από άχρηστη γνώση και καρδιά χωρίς φόβο στον Αλλάχ.", "Μια ντουέτα καταφυγής από τον Προφήτη ﷺ."),
        "dua_beneficial_knowledge" to DuaText("Ευεργετική Γνώση & Halal Rizq", "Ω Αλλάχ, Σου ζητώ ωφέλιμη γνώση, καθαρή πρόνοια και αποδεκτές πράξεις.", "Μετά την προσευχή του Fajr.", "Ο Προφήτης ﷺ το είπε αυτό μετά το σαλάμ του Φατζρ."),
        "dua_leprosy_diseases" to DuaText("Καταφύγιο από σοβαρές ασθένειες", "Ω Αλλάχ, ζητώ καταφύγιο σε Σένα από τη λεύκη, την τρέλα, τη λέπρα και όλες τις κακές ασθένειες.", "Προστασία από σοβαρές ασθένειες.", "Ένα Sunnah dua για τη διατήρηση της υγείας."),
        "dua_fear_people" to DuaText("Φόβος εχθρών ή καταπιεστών", "Ω Αλλάχ, σε τοποθετούμε μπροστά τους και ζητάμε καταφύγιο σε Σένα από το κακό τους.", "Όταν φοβόμαστε τη ζημιά ενός λαού ή ενός ατόμου.", "Ο Προφήτης ﷺ το είπε αυτό όταν φοβόταν έναν λαό."),
        "dua_shirk_protection" to DuaText("Προστασία από το κρυφό Shirk", "Ω Αλλάχ, αναζητώ καταφύγιο σε Σένα από το να συναναστρέφομαι εν γνώσει σου οτιδήποτε, και ζητώ τη συγχώρεση Σου για ό,τι κάνω εν αγνοία μου.", "Για να μείνουμε ασφαλείς από την επίδειξη και το κρυφό σιρκ.", "Το κρυμμένο σιρκ είναι πιο κρυμμένο από το ερπυσμό ενός μυρμηγκιού."),
        "dua_rain" to DuaText("Όταν βρέχει", "Ω Αλλάχ, (στείλε) μια ευεργετική βροχή.", "Όταν βρέχει.", "Η βροχή είναι μια εποχή που γίνονται αποδεκτές οι ντους."),
        "dua_after_rain" to DuaText("Μετά τη Βροχή", "Μας έχει δοθεί βροχή από τη γενναιοδωρία του Αλλάχ και το έλεός Του.", "Μετά από βροχή.", "Αυτός που το λέει αυτό είναι πιστός στον Αλλάχ."),
        "dua_istisqa" to DuaText("Ζητώντας τη βροχή (Istisqa)", "Ω Αλλάχ, στείλε μας βροχή (τρεις φορές).", "Όταν δεν βρέχει.", "Ο Προφήτης ﷺ έκανε αυτή τη ντουά στο κήρυγμα της Παρασκευής και έβρεξε."),
        "dua_heavy_rain" to DuaText("Υπερβολική βροχή", "Ω Αλλάχ, (ας πέσει) γύρω μας και όχι πάνω μας.", "Όταν βρέχει πάρα πολύ.", "Τα σύννεφα απομακρύνθηκαν μέσω της ντουέτας του Προφήτη ﷺ."),
        "dua_wind" to DuaText("Όταν φυσάει ο άνεμος", "Ω Αλλάχ, Σου ζητώ το καλό του, το καλό μέσα του και το καλό με αυτό με το οποίο στάλθηκε, και ζητώ καταφύγιο σε Σένα από το κακό του, το κακό μέσα του και το κακό με αυτό με το οποίο στάλθηκε.", "Όταν φυσάει δυνατός άνεμος ή καταιγίδα.", "Ο Προφήτης ﷺ έκανε αυτή τη ντουά κατά τη διάρκεια καταιγίδων."),
        "dua_thunder" to DuaText("Ακούγοντας βροντή", "Δόξα σ' Αυτόν που η βροντή δοξάζει με τον έπαινο Του, και οι άγγελοι από φόβο Του.", "Στο άκουσμα βροντής — η πρακτική του Abdullah ibn az-Zubayr (RA).", "Λήψη από τη Surah ar-Ra'd (13:13)."),
        "dua_new_moon" to DuaText("Βλέποντας τη Νέα Σελήνη", "Ω Αλλάχ, αφήστε αυτό το φεγγάρι να ανατείλει από πάνω μας με ευλογία, πίστη, ασφάλεια και Ισλάμ. (Ω φεγγάρι), ο Κύριός μου και ο Κύριός σου είναι ο Αλλάχ.", "Βλέποντας τη νέα σελήνη.", "Το Sunnah dua για κάθε νέο μήνα."),
        "dua_janaza_adult" to DuaText("Προσευχή Janaza (Ενήλικες)", "Ω Αλλάχ, συγχώρεσε τους ζωντανούς και τους νεκρούς μας, τους παρόντες και τους απόντες, τους νέους και τους ηλικιωμένους μας, τους άνδρες και τις γυναίκες μας. Ω Αλλάχ, όποιον από εμάς κρατάς ζωντανό, κράτα τον ζωντανό στο Ισλάμ, και όποιον από εμάς κάνεις να πεθάνει, κάνε τον να πεθάνει με πίστη.", "Μετά το τρίτο τακμπίρ της νεκρώσιμης προσευχής.", "Το Sunnah dua για έναν νεκρό ενήλικα."),
        "dua_janaza_child" to DuaText("Προσευχή Janaza (Παιδί)", "Ω Αλλάχ, κάνε τον πρόδρομο (και οικοδεσπότη) για μας, κάνε τον ανταμοιβή και θησαυρό για εμάς και κάνε τον μεσιτεία για εμάς που η μεσιτεία του γίνεται δεκτή.", "Στην επικήδειο προσευχή ενός παιδιού (για ένα κορίτσι πείτε \"ij'alhā\").", "Το Sunnah dua που ασκούν οι Χαναφί."),
        "dua_mayyit_awf" to DuaText("Αναλυτικά Dua για τον νεκρό", "Ω Αλλάχ, συγχώρεσέ τον, ελέησέ τον, δώσε του ευημερία και συγχώρεσέ τον. Κάνε την υποδοχή του τιμητική και τον τάφο του ευρύχωρο, πλύνε τον με νερό, χιόνι και χαλάζι, και καθάρισέ τον από τις αμαρτίες, όπως καθαρίζεται το λευκό ένδυμα από τη βρωμιά.", "Στη νεκρώσιμη δέηση ή για τον νεκρό.", "Ο Awf ibn Malik (RA) ευχήθηκε να ήταν εκείνο το νεκρό άτομο."),
        "dua_visiting_graves" to DuaText("Επίσκεψη στους Τάφους", "Ειρήνη σε εσάς, ω πιστοί και μουσουλμάνοι κάτοικοι αυτών των σπιτιών. Κι εμείς, αν θέλει ο Αλλάχ, θα ενώσουμε μαζί σας. Ζητώ από τον Αλλάχ για ευημερία για εμάς και για εσάς.", "Κατά την είσοδο στο νεκροταφείο.", "Η επίσκεψη στους τάφους θυμίζει τον θάνατο και το επέκεινα."),
        "dua_closing_eyes" to DuaText("Με το κλείσιμο των ματιών του νεκρού", "Ω Αλλάχ, συγχώρεσε (όνομα), ανέβασε την κατάταξή του μεταξύ των καθοδηγούμενων, γίνε ο διάδοχός του ανάμεσα σε αυτούς που αφήνει πίσω. Συγχώρεσέ εμάς και αυτόν, Κύριε των κόσμων. κάνε τον τάφο του ευρύχωρο και γέμισε τον με φως.", "Όταν κλείνουν τα μάτια του νεκρού (αναφέροντας το όνομά του).", "Ο Προφήτης ﷺ έκανε αυτή τη ντουά για τον Αμπού Σαλαμά (RA)."),
        "dua_condolence" to DuaText("Συλλυπητήρια (Ta'ziyah)", "Σίγουρα στον Αλλάχ ανήκει ό,τι πήρε και σε Αυτόν ανήκει ό,τι έδωσε, και όλα μαζί Του έχουν καθορισμένο χρόνο, γι' αυτό κάνε υπομονή και ελπίζεις σε ανταμοιβή.", "Συλλυπητήρια σε μια οικογένεια μετά από θάνατο.", "Ο Προφήτης ﷺ έστειλε αυτό το μήνυμα στην κόρη του."),
        "dua_placing_in_grave" to DuaText("Τοποθέτηση του νεκρού στον τάφο", "Στο όνομα του Αλλάχ και στο δρόμο του Αγγελιαφόρου του Αλλάχ ﷺ.", "Όταν κατεβάζουν τον νεκρό στον τάφο.", "Το Sunnah dua της ταφής."),
        "dua_sneezing" to DuaText("Φτάρνισμα", "Όλος ο έπαινος είναι για τον Αλλάχ. — Είθε ο Αλλάχ να σας ελεήσει. — Είθε ο Αλλάχ να σας καθοδηγήσει και να διορθώσει τις υποθέσεις σας.", "Στο φτέρνισμα? ο ακροατής λέει «Yarhamukallah» και μετά απαντά αυτός που φτερνίστηκε.", "Είναι ένα από τα δικαιώματα ενός μουσουλμάνου έναντι ενός άλλου μουσουλμάνου."),
        "dua_toilet_enter" to DuaText("Μπαίνοντας στην τουαλέτα", "Στο όνομα του Αλλάχ. Ω Αλλάχ, ζητώ καταφύγιο σε Σένα από τα αρσενικά και τα ακάθαρτα τζιν.", "Πριν μπείτε στην τουαλέτα με το αριστερό πόδι.", "Η Bismillah γίνεται μια οθόνη ανάμεσα στο τζιν και το άτομο."),
        "dua_toilet_exit" to DuaText("Φεύγοντας από την τουαλέτα", "(Ω Αλλάχ,) Ζητώ τη συγχώρεση Σου.", "Όταν βγαίνετε από την τουαλέτα με το δεξί πόδι.", "Ο Προφήτης ﷺ το είπε φεύγοντας από την τουαλέτα."),
        "dua_thanking" to DuaText("Ευχαριστώ κάποιον", "Είθε ο Αλλάχ να σας ανταμείψει με καλό.", "Όταν κάποιος σου κάνει μια χάρη.", "Όποιος το λέει αυτό έχει εκφράσει πλήρως τις ευχαριστίες του."),
        "dua_love_for_allah" to DuaText("Όταν κάποιος λέει \"Σ 'αγαπώ για τον Αλλάχ\"", "Είθε να σε αγαπήσει Αυτός (ο Αλλάχ), για χάρη του οποίου με αγαπάς.", "Όταν κάποιος λέει \"σ' αγαπώ για χάρη του Αλλάχ\".", "Η Σούννα απαντά στην αγάπη για χάρη του Αλλάχ."),
        "dua_seeing_muslim_smile" to DuaText("Χαιρετισμός (Salaam)", "Ειρήνη σε σας, και το έλεος του Αλλάχ και οι ευλογίες Του.", "Όταν συναντάς έναν μουσουλμάνο.", "Το να πεις το πλήρες σαλάμ κερδίζεις τριάντα καλές πράξεις."),
        "dua_dressing" to DuaText("Να ντύνονται", "Όλος ο έπαινος είναι για τον Αλλάχ που με έντυσε με αυτό και μου το παρείχε χωρίς καμία δύναμη ή δύναμη εκ μέρους μου.", "Όταν ντύνομαι.", "Χαρούμενα νέα για συγχώρεση προηγούμενων αμαρτιών."),
    )
}
